def _line_total(item):
    return item["quantity"] * item["unit_price"]


def subtotal(items):
    return sum(_line_total(item) for item in items)


def tax(items, rate):
    return round(subtotal(items) * rate)


def grand_total(items, rate):
    base = subtotal(items)
    return base + round(base * rate)
